-- ============================================================
-- LIMITGUARD DATABASE INITIALIZATION
-- Baseline version: 001
-- ============================================================
--
-- Purpose:
-- Create the PostgreSQL schema required by:
--   1. Auth Service
--   2. Credit Service
--   3. Activity Service
--
-- All three services share one PostgreSQL database.
--
-- IMPORTANT:
--   - Run this script only against an EMPTY public schema.
--   - This script creates database structures, not demo data.
--   - The demo seeders populate the tables separately.
--   - Hibernate ddl-auto=validate checks the schema afterward.
--
-- Run using psql with the appropriate database connection:
--
-- psql -X --set=ON_ERROR_STOP=1 --file=database/schema.sql
--
-- ============================================================


-- ============================================================
-- 1. INITIALIZATION TRANSACTION AND SAFETY CHECKS
-- ============================================================

-- Start a transaction.
-- The database changes are committed together at the end.
BEGIN;

-- Use PostgreSQL's built-in catalog and the public schema.
SET LOCAL search_path = pg_catalog, public;

-- Prevent competing initialization processes from running
-- this baseline simultaneously.
SELECT pg_advisory_xact_lock(724211, 2);


-- Check whether the public schema already contains objects.
-- pg_class stores information about database objects.
-- pg_namespace identifies which schema an object belongs to.
--
-- The listed relkind values represent:
--   r = ordinary table
--   p = partitioned table
--   v = view
--   m = materialized view
--   f = foreign table
--   S = sequence
--   c = composite type
--
-- If any matching object exists, initialization is rejected.
-- This protects an already initialized database.

DO $bootstrap$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM pg_class c
        JOIN pg_namespace n
            ON n.oid = c.relnamespace
        WHERE n.nspname = 'public'
          AND c.relkind IN (
              'r', 'p', 'v', 'm', 'f', 'S', 'c'
          )
    ) THEN
        RAISE EXCEPTION
            'LimitGuard baseline requires an empty public schema';
END IF;
END
$bootstrap$;


-- ============================================================
-- 2. AUTH SERVICE AND SHARED AUDIT TABLES
-- ============================================================


-- ------------------------------------------------------------
-- TABLE 1: financial_institutions
-- ------------------------------------------------------------
-- Stores banks that use LimitGuard.
--
-- Example:
--   Citi
--   Gulf International Bank
--
-- id:
--   Automatically generated primary key.
--
-- status:
--   Only ACTIVE or INACTIVE is allowed.
--
-- UNIQUE(name):
--   Prevents two institutions from having the same name.

CREATE TABLE public.financial_institutions (
                                               id bigint GENERATED BY DEFAULT AS IDENTITY,
                                               created_at timestamp(6) without time zone NOT NULL,
                                               name varchar(255) NOT NULL,
                                               status varchar(255) NOT NULL,
                                               updated_at timestamp(6) without time zone NOT NULL,

                                               CONSTRAINT financial_institutions_status_check
                                                   CHECK (
                                                       status IN (
                                                                  'ACTIVE',
                                                                  'INACTIVE'
                                                           )
                                                       ),

                                               CONSTRAINT financial_institutions_pkey
                                                   PRIMARY KEY (id),

                                               CONSTRAINT uknrxiiwuih8wajrl6i74hsouk1
                                                   UNIQUE (name)
);


-- ------------------------------------------------------------
-- TABLE 2: users
-- ------------------------------------------------------------
-- Stores registered LimitGuard users.
--
-- Each user belongs to a financial institution.
--
-- Roles:
--   RELATIONSHIP_MANAGER
--   RISK_OFFICER
--   ADMIN
--
-- email_verified:
--   Indicates whether the user verified their email.
--
-- password:
--   Stores the password representation used by the application.
--   The application must store password hashes, not plaintext.
--
-- financial_institution_id:
--   Connects the user to a bank.
--   Its foreign key is declared later.

CREATE TABLE public.users (
                              id bigint GENERATED BY DEFAULT AS IDENTITY,
                              created_at timestamp(6) without time zone NOT NULL,
                              email varchar(255) NOT NULL,
                              email_verified boolean NOT NULL,
                              first_name varchar(255) NOT NULL,
                              last_name varchar(255) NOT NULL,
                              password varchar(255) NOT NULL,
                              profile_picture_path varchar(255),
                              role varchar(255) NOT NULL,
                              status varchar(255) NOT NULL,
                              updated_at timestamp(6) without time zone NOT NULL,
                              financial_institution_id bigint NOT NULL,

                              CONSTRAINT users_role_check
                                  CHECK (
                                      role IN (
                                               'RELATIONSHIP_MANAGER',
                                               'RISK_OFFICER',
                                               'ADMIN'
                                          )
                                      ),

                              CONSTRAINT users_status_check
                                  CHECK (
                                      status IN (
                                                 'ACTIVE',
                                                 'DEACTIVATED'
                                          )
                                      ),

                              CONSTRAINT uk6dotkott2kjsp8vw4d0m25fb7
                                  UNIQUE (email),

                              CONSTRAINT users_pkey
                                  PRIMARY KEY (id)
);


-- ------------------------------------------------------------
-- TABLE 3: email_verification_codes
-- ------------------------------------------------------------
-- Stores challenges used during email verification.
--
-- attempts:
--   Number of verification attempts.
--
-- challenge_id:
--   Unique identifier for the challenge.
--
-- code_digest:
--   Digest of the verification code.
--
-- expires_at:
--   Time after which the challenge expires.
--
-- resend_after:
--   Earliest time another code may be requested.
--
-- used:
--   Indicates whether the challenge has been consumed.
--
-- UNIQUE(user_id):
--   Allows at most one row per user in this table.

CREATE TABLE public.email_verification_codes (
                                                 id bigint GENERATED BY DEFAULT AS IDENTITY,
                                                 attempts integer NOT NULL,
                                                 challenge_id varchar(255) NOT NULL,
                                                 code_digest varchar(255) NOT NULL,
                                                 expires_at timestamp(6) with time zone NOT NULL,
                                                 resend_after timestamp(6) with time zone NOT NULL,
                                                 used boolean NOT NULL,
                                                 user_id bigint NOT NULL,

                                                 CONSTRAINT email_verification_codes_pkey
                                                     PRIMARY KEY (id),

                                                 CONSTRAINT ukjj9p4a2fjk5cm5m1oeeeglsmm
                                                     UNIQUE (challenge_id),

                                                 CONSTRAINT uktial04bb66yjnh7c6g56nvwws
                                                     UNIQUE (user_id)
);


-- ------------------------------------------------------------
-- TABLE 4: password_reset_codes
-- ------------------------------------------------------------
-- Stores password reset challenges.
--
-- A user can request a password reset.
-- The challenge must be verified before resetting the password.
--
-- user_id is nullable because a reset challenge may not
-- necessarily have an associated user reference.

CREATE TABLE public.password_reset_codes (
                                             id bigint GENERATED BY DEFAULT AS IDENTITY,
                                             attempts integer NOT NULL,
                                             challenge_id varchar(255) NOT NULL,
                                             code_digest varchar(255) NOT NULL,
                                             email varchar(255) NOT NULL,
                                             expires_at timestamp(6) with time zone NOT NULL,
                                             resend_after timestamp(6) with time zone NOT NULL,
                                             used boolean NOT NULL,
                                             user_id bigint,

                                             CONSTRAINT password_reset_codes_pkey
                                                 PRIMARY KEY (id),

                                             CONSTRAINT ukbk5v8o9pr8pxcnpn26ygvi503
                                                 UNIQUE (email),

                                             CONSTRAINT ukj9qviffaxsemoqw7ir511tqeb
                                                 UNIQUE (challenge_id)
);


-- ------------------------------------------------------------
-- TABLE 5: user_tokens
-- ------------------------------------------------------------
-- Stores tokens for email verification and password resets.
--
-- token_type:
--   Restricted to the supported token categories.
--
-- used:
--   Tracks whether a token has been consumed.
--
-- UNIQUE(token):
--   Prevents duplicate token values.

CREATE TABLE public.user_tokens (
                                    id bigint GENERATED BY DEFAULT AS IDENTITY,
                                    created_at timestamp(6) without time zone NOT NULL,
                                    expires_at timestamp(6) without time zone NOT NULL,
                                    token varchar(255) NOT NULL,
                                    token_type varchar(255) NOT NULL,
                                    used boolean NOT NULL,
                                    user_id bigint NOT NULL,

                                    CONSTRAINT user_tokens_token_type_check
                                        CHECK (
                                            token_type IN (
                                                           'EMAIL_VERIFICATION',
                                                           'PASSWORD_RESET'
                                                )
                                            ),

                                    CONSTRAINT ukfvl6k04x11pern525noiw5k6v
                                        UNIQUE (token),

                                    CONSTRAINT user_tokens_pkey
                                        PRIMARY KEY (id)
);


-- ------------------------------------------------------------
-- TABLE 6: audit_logs
-- ------------------------------------------------------------
-- Shared audit log used by Auth and Credit.
--
-- Records important system and business actions.
--
-- Example:
--   A Risk Officer approves a credit request.
--
-- action:
--   The operation performed.
--
-- entity_type and entity_id:
--   Identify the affected business object.
--
-- actor_id:
--   User responsible for the action, if available.
--
-- financial_institution_id:
--   Institution associated with the audit record.
--
-- details:
--   Additional audit information.
--
-- This is ONE shared table, not a separate audit table
-- for each microservice.

CREATE TABLE public.audit_logs (
                                   id bigint GENERATED BY DEFAULT AS IDENTITY,
                                   action varchar(255) NOT NULL,
                                   created_at timestamp(6) without time zone NOT NULL,
                                   details text,
                                   entity_id bigint NOT NULL,
                                   entity_type varchar(255) NOT NULL,
                                   actor_id bigint,
                                   financial_institution_id bigint,

                                   CONSTRAINT audit_logs_pkey
                                       PRIMARY KEY (id)
);


-- ============================================================
-- 3. CREDIT SERVICE TABLES
-- ============================================================


-- ------------------------------------------------------------
-- TABLE 7: counterparties
-- ------------------------------------------------------------
-- Stores companies that banks manage credit exposure for.
--
-- A counterparty may be:
--   ACTIVE
--   FROZEN
--   CLOSED
--
-- A frozen counterparty is subject to restrictions
-- enforced by the application's business logic.

CREATE TABLE public.counterparties (
                                       id bigint GENERATED BY DEFAULT AS IDENTITY,
                                       created_at timestamp(6) without time zone NOT NULL,
                                       name varchar(255) NOT NULL,
                                       status varchar(255) NOT NULL,
                                       updated_at timestamp(6) without time zone NOT NULL,

                                       CONSTRAINT counterparties_status_check
                                           CHECK (
                                               status IN (
                                                          'ACTIVE',
                                                          'FROZEN',
                                                          'CLOSED'
                                                   )
                                               ),

                                       CONSTRAINT counterparties_pkey
                                           PRIMARY KEY (id),

                                       CONSTRAINT uktmhf78babtq0qdm5twwfk8mth
                                           UNIQUE (name)
);


-- ------------------------------------------------------------
-- TABLE 8: corporate_groups
-- ------------------------------------------------------------
-- Stores groups of related companies.
--
-- Example:
--   North Reef Holdings
--
-- A corporate group can contain multiple counterparties.
-- The memberships table represents those relationships.

CREATE TABLE public.corporate_groups (
                                         id bigint GENERATED BY DEFAULT AS IDENTITY,
                                         created_at timestamp(6) without time zone NOT NULL,
                                         name varchar(255) NOT NULL,
                                         updated_at timestamp(6) without time zone NOT NULL,

                                         CONSTRAINT corporate_groups_pkey
                                             PRIMARY KEY (id),

                                         CONSTRAINT ukrw9x5xhf7y35fd6xda8n5jm76
                                             UNIQUE (name)
);


-- ------------------------------------------------------------
-- TABLE 9: corporate_group_memberships
-- ------------------------------------------------------------
-- Links counterparties to corporate groups.
--
-- corporate_group_id:
--   The parent corporate group.
--
-- counterparty_id:
--   The company belonging to that group.
--
-- UNIQUE(counterparty_id):
--   A company can appear in at most one group membership.

CREATE TABLE public.corporate_group_memberships (
                                                    id bigint GENERATED BY DEFAULT AS IDENTITY,
                                                    corporate_group_id bigint NOT NULL,
                                                    counterparty_id bigint NOT NULL,

                                                    CONSTRAINT corporate_group_memberships_pkey
                                                        PRIMARY KEY (id),

                                                    CONSTRAINT uk2uoo946txpe0bg3srmkwehkv9
                                                        UNIQUE (counterparty_id)
);


-- ------------------------------------------------------------
-- TABLE 10: counterparty_financial_profiles
-- ------------------------------------------------------------
-- Stores financial information about counterparties.
--
-- The six financial ratios are used by the experimental
-- ML risk prediction feature.
--
-- numeric(18,6):
--   Fixed-precision numeric value with up to 18 digits
--   in total, including 6 digits after the decimal point.
--
-- UNIQUE(counterparty_id):
--   One financial profile per counterparty in this schema.

CREATE TABLE public.counterparty_financial_profiles (
                                                        id bigint GENERATED BY DEFAULT AS IDENTITY,
                                                        created_at timestamp(6) without time zone NOT NULL,
                                                        debt_to_total_capital_percent numeric(18,6) NOT NULL,
                                                        financial_year_end date NOT NULL,
                                                        fixed_asset_turnover numeric(18,6) NOT NULL,
                                                        interest_coverage numeric(18,6) NOT NULL,
                                                        profit_margin numeric(18,6) NOT NULL,
                                                        return_on_assets numeric(18,6) NOT NULL,
                                                        total_debt_to_ebitda numeric(18,6) NOT NULL,
                                                        updated_at timestamp(6) without time zone NOT NULL,
                                                        counterparty_id bigint NOT NULL,

                                                        CONSTRAINT counterparty_financial_profiles_pkey
                                                            PRIMARY KEY (id),

                                                        CONSTRAINT uk56wtypd5mf26y2412455i5jw
                                                            UNIQUE (counterparty_id)
);


-- ------------------------------------------------------------
-- TABLE 11: credit_limits
-- ------------------------------------------------------------
-- Stores company-level credit facilities.
--
-- limit_amount:
--   Maximum credit facility amount.
--
-- used_amount:
--   Credit already utilized.
--
-- reserved_amount:
--   Credit reserved for approved requests.
--
-- Available headroom:
--   limit_amount - used_amount - reserved_amount
--
-- Example:
--   Limit:     BHD 500,000
--   Used:      BHD 100,000
--   Reserved:  BHD  50,000
--   Headroom:  BHD 350,000
--
-- UNIQUE(financial_institution_id, counterparty_id):
--   One credit facility per bank-company combination.

CREATE TABLE public.credit_limits (
                                      id bigint GENERATED BY DEFAULT AS IDENTITY,
                                      created_at timestamp(6) without time zone NOT NULL,
                                      limit_amount numeric(19,2) NOT NULL,
                                      reserved_amount numeric(19,2) NOT NULL,
                                      updated_at timestamp(6) without time zone NOT NULL,
                                      used_amount numeric(19,2) NOT NULL,
                                      counterparty_id bigint NOT NULL,
                                      financial_institution_id bigint NOT NULL,

                                      CONSTRAINT credit_limits_pkey
                                          PRIMARY KEY (id),

                                      CONSTRAINT ukivfbth17srdb27017sw2mu20q
                                          UNIQUE (
                                                  financial_institution_id,
                                                  counterparty_id
                                              )
);


-- ------------------------------------------------------------
-- TABLE 12: group_credit_limits
-- ------------------------------------------------------------
-- Stores credit limits assigned to corporate groups.
--
-- amount:
--   Approved group-level limit.
--
-- UNIQUE(financial_institution_id, corporate_group_id):
--   A bank can have at most one group credit limit
--   for each corporate group.

CREATE TABLE public.group_credit_limits (
                                            id bigint GENERATED BY DEFAULT AS IDENTITY,
                                            amount numeric(19,2) NOT NULL,
                                            created_at timestamp(6) without time zone NOT NULL,
                                            updated_at timestamp(6) without time zone NOT NULL,
                                            corporate_group_id bigint NOT NULL,
                                            financial_institution_id bigint NOT NULL,

                                            CONSTRAINT group_credit_limits_pkey
                                                PRIMARY KEY (id),

                                            CONSTRAINT uk_group_credit_limit_bank_group
                                                UNIQUE (
                                                        financial_institution_id,
                                                        corporate_group_id
                                                    )
);


-- ------------------------------------------------------------
-- TABLE 13: credit_requests
-- ------------------------------------------------------------
-- Stores credit requests submitted by users.
--
-- Typical workflow:
--   1. Relationship Manager creates a request.
--   2. Request enters PENDING_APPROVAL.
--   3. Risk Officer reviews the request.
--   4. Request may be approved or rejected.
--   5. Approved credit may become reserved and then used.
--
-- status:
--   Restricted to the defined request states.
--
-- requester_id:
--   The user who created the request.
--
-- credit_limit_id:
--   The facility associated with the request.
--
-- seed_key:
--   Optional identifier used by demo seeding.

CREATE TABLE public.credit_requests (
                                        id bigint GENERATED BY DEFAULT AS IDENTITY,
                                        amount numeric(19,2) NOT NULL,
                                        created_at timestamp(6) without time zone NOT NULL,
                                        expires_at timestamp(6) without time zone,
                                        status varchar(255) NOT NULL,
                                        updated_at timestamp(6) without time zone NOT NULL,
                                        credit_limit_id bigint NOT NULL,
                                        requester_id bigint NOT NULL,
                                        seed_key varchar(255),

                                        CONSTRAINT credit_requests_status_check
                                            CHECK (
                                                status IN (
                                                           'PENDING_APPROVAL',
                                                           'RESERVED',
                                                           'USED',
                                                           'REJECTED',
                                                           'CANCELLED',
                                                           'EXPIRED'
                                                    )
                                                ),

                                        CONSTRAINT credit_requests_pkey
                                            PRIMARY KEY (id),

                                        CONSTRAINT uk69bobn8qatkrocu4qkqk83ki5
                                            UNIQUE (seed_key)
);


-- ------------------------------------------------------------
-- TABLE 14: approval_decisions
-- ------------------------------------------------------------
-- Stores approval decisions made by Risk Officers.
--
-- decision:
--   APPROVED or REJECTED.
--
-- decided_by_id:
--   User who made the decision.
--
-- credit_request_id:
--   Request being reviewed.
--
-- UNIQUE(credit_request_id):
--   Prevents multiple decision records for one request.

CREATE TABLE public.approval_decisions (
                                           id bigint GENERATED BY DEFAULT AS IDENTITY,
                                           created_at timestamp(6) without time zone NOT NULL,
                                           decision varchar(255) NOT NULL,
                                           reason varchar(255),
                                           credit_request_id bigint NOT NULL,
                                           decided_by_id bigint NOT NULL,

                                           CONSTRAINT approval_decisions_decision_check
                                               CHECK (
                                                   decision IN (
                                                                'APPROVED',
                                                                'REJECTED'
                                                       )
                                                   ),

                                           CONSTRAINT approval_decisions_pkey
                                               PRIMARY KEY (id),

                                           CONSTRAINT unique_credit_request_decision
                                               UNIQUE (credit_request_id)
);


-- ------------------------------------------------------------
-- TABLE 15: credit_exposure_snapshots
-- ------------------------------------------------------------
-- Stores historical credit exposure snapshots.
--
-- Used to record exposure values for reporting dates.
--
-- institution_id:
--   Institution associated with the snapshot.
--
-- facility_id:
--   Credit facility being recorded.
--
-- reporting_date:
--   Date represented by the snapshot.
--
-- captured_at:
--   Timestamp when the snapshot was recorded.
--
-- COMPOSITE PRIMARY KEY:
--   institution_id + facility_id + reporting_date
--
-- This means the combination of these three values
-- must be unique.

CREATE TABLE public.credit_exposure_snapshots (
                                                  institution_id bigint NOT NULL,
                                                  facility_id bigint NOT NULL,
                                                  captured_at timestamp with time zone NOT NULL,
                                                  reporting_date date NOT NULL,
                                                  limit_amount numeric(19,2) NOT NULL,
                                                  used_amount numeric(19,2) NOT NULL,
                                                  reserved_amount numeric(19,2) NOT NULL,

                                                  CONSTRAINT credit_exposure_snapshots_pkey
                                                      PRIMARY KEY (
                                                                   institution_id,
                                                                   facility_id,
                                                                   reporting_date
                                                          )
);


-- ------------------------------------------------------------
-- TABLE 16: notification_outbox
-- ------------------------------------------------------------
-- Stores events created by the Credit Service.
--
-- Supports the transactional outbox pattern.
--
-- Example workflow:
--   1. A credit request is approved.
--   2. Credit Service saves the business change.
--   3. A notification event is stored in this table.
--   4. An outbox publisher sends the event to Kafka.
--   5. Activity Service can consume the event.
--
-- published_at:
--   Indicates when the event was published.
--
-- The CHECK constraint validates event-specific fields.
--
-- PostgreSQL functions used:
--
-- btrim(value):
--   Removes surrounding spaces from text.
--
-- num_nonnulls(...):
--   Counts how many supplied values are not NULL.
--
-- IS TRUE:
--   Requires the CASE result to be explicitly TRUE.
--   FALSE and NULL are both rejected.
--
-- These checks prevent malformed event records.

CREATE TABLE public.notification_outbox (
                                            id bigint GENERATED BY DEFAULT AS IDENTITY,
                                            created_at timestamp(6) without time zone NOT NULL,
                                            credit_request_id bigint,
                                            event_type varchar(255) NOT NULL,
                                            financial_institution_id bigint NOT NULL,
                                            published_at timestamp(6) without time zone,
                                            reason text,
                                            requester_id bigint,
                                            status varchar(255),
                                            counterparty_id bigint,
                                            credit_limit_id bigint,
                                            group_credit_limit_id bigint,
                                            corporate_group_id bigint,
                                            old_limit_amount numeric(19,2),
                                            new_limit_amount numeric(19,2),

                                            CONSTRAINT notification_outbox_event_fields_check
                                                CHECK (
                                                    (
                                                        CASE

                                                            -- Credit request events:
                                                            -- Require request ID, requester ID, and
                                                            -- a non-empty status.
                                                            --
                                                            -- Other event-specific fields must be NULL.

                                                            WHEN event_type IN (
                                                                                'CREDIT_REQUEST_CREATED',
                                                                                'CREDIT_REQUEST_APPROVED',
                                                                                'CREDIT_REQUEST_REJECTED',
                                                                                'CREDIT_REQUEST_USED',
                                                                                'CREDIT_REQUEST_CANCELLED',
                                                                                'CREDIT_REQUEST_EXPIRED'
                                                                )
                                                                THEN
                                                                credit_request_id IS NOT NULL
                                                                    AND requester_id IS NOT NULL
                                                                    AND btrim(status) <> ''
                                                                    AND num_nonnulls(
                                                                                counterparty_id,
                                                                                credit_limit_id,
                                                                                group_credit_limit_id,
                                                                                corporate_group_id,
                                                                                old_limit_amount,
                                                                                new_limit_amount
                                                                        ) = 0

                                                            -- Counterparty status events:
                                                            -- Require a counterparty ID and
                                                            -- an allowed status.
                                                            --
                                                            -- Unrelated event fields must be NULL.

                                                            WHEN event_type = 'COUNTERPARTY_STATUS_UPDATED'
                                                                THEN
                                                                counterparty_id IS NOT NULL
                                                                    AND status IN (
                                                                                   'ACTIVE',
                                                                                   'FROZEN',
                                                                                   'CLOSED'
                                                                    )
                                                                    AND num_nonnulls(
                                                                                credit_request_id,
                                                                                requester_id,
                                                                                credit_limit_id,
                                                                                group_credit_limit_id,
                                                                                corporate_group_id,
                                                                                old_limit_amount,
                                                                                new_limit_amount
                                                                        ) = 0

                                                            -- Individual credit limit updates:
                                                            -- Require the facility ID and both
                                                            -- the previous and new limit amounts.

                                                            WHEN event_type = 'CREDIT_LIMIT_UPDATED'
                                                                THEN
                                                                credit_limit_id IS NOT NULL
                                                                    AND old_limit_amount IS NOT NULL
                                                                    AND new_limit_amount IS NOT NULL
                                                                    AND num_nonnulls(
                                                                                credit_request_id,
                                                                                requester_id,
                                                                                status,
                                                                                counterparty_id,
                                                                                group_credit_limit_id,
                                                                                corporate_group_id
                                                                        ) = 0

                                                            -- Group credit limit updates:
                                                            -- Require the group facility ID,
                                                            -- corporate group ID, and old/new amounts.

                                                            WHEN event_type = 'GROUP_CREDIT_LIMIT_UPDATED'
                                                                THEN
                                                                group_credit_limit_id IS NOT NULL
                                                                    AND corporate_group_id IS NOT NULL
                                                                    AND old_limit_amount IS NOT NULL
                                                                    AND new_limit_amount IS NOT NULL
                                                                    AND num_nonnulls(
                                                                                credit_request_id,
                                                                                requester_id,
                                                                                status,
                                                                                counterparty_id,
                                                                                credit_limit_id
                                                                        ) = 0

                                                            -- Any unsupported event type is rejected.
                                                            ELSE false

                                                            END
                                                        ) IS TRUE
                                                    ),

                                            CONSTRAINT notification_outbox_pkey
                                                PRIMARY KEY (id)
);


-- ============================================================
-- 4. ACTIVITY SERVICE TABLE
-- ============================================================


-- ------------------------------------------------------------
-- TABLE 17: credit_request_email_deliveries
-- ------------------------------------------------------------
-- Stores email delivery records for credit request events.
--
-- Activity Service uses this table for its delivery queue.
--
-- Supported events:
--   CREDIT_REQUEST_APPROVED
--   CREDIT_REQUEST_REJECTED
--   CREDIT_REQUEST_EXPIRED
--
-- event_id:
--   Primary key for the event.
--   Prevents duplicate delivery records for the same event.
--
-- delivery_status:
--   Defaults to PENDING.
--
-- queued_at:
--   Defaults to the current timestamp.
--
-- The application handles the actual delivery workflow.

CREATE TABLE public.credit_request_email_deliveries (
                                                        event_id bigint NOT NULL,
                                                        financial_institution_id bigint NOT NULL,
                                                        credit_request_id bigint NOT NULL,
                                                        requester_id bigint NOT NULL,
                                                        event_type varchar(64) NOT NULL,
                                                        reason text,

                                                        delivery_status varchar(16)
                                                            DEFAULT 'PENDING' NOT NULL,

                                                        queued_at timestamp with time zone
                                                            DEFAULT CURRENT_TIMESTAMP NOT NULL,

                                                        CONSTRAINT credit_request_email_deliveries_event_type_check
                                                            CHECK (
                                                                event_type IN (
                                                                               'CREDIT_REQUEST_APPROVED',
                                                                               'CREDIT_REQUEST_REJECTED',
                                                                               'CREDIT_REQUEST_EXPIRED'
                                                                    )
                                                                ),

                                                        CONSTRAINT credit_request_email_deliveries_pkey
                                                            PRIMARY KEY (event_id)
);


-- ============================================================
-- 5. FOREIGN KEY RELATIONSHIPS
-- ============================================================
--
-- A foreign key connects records in different tables.
--
-- Example:
--   users.financial_institution_id
--       references
--   financial_institutions.id
--
-- This means a user cannot reference a bank that does
-- not exist in the financial_institutions table.
--
-- Foreign keys help maintain referential integrity.
--
-- All referenced tables have been created above.
-- We can now add their relationships.
--
-- ============================================================


-- Audit log belongs to an institution, when specified.
ALTER TABLE ONLY public.audit_logs
    ADD CONSTRAINT fk37kqs723fn382ks5ywvh5usck
    FOREIGN KEY (financial_institution_id)
    REFERENCES public.financial_institutions(id);


-- Each approval decision belongs to a credit request.
ALTER TABLE ONLY public.approval_decisions
    ADD CONSTRAINT fk3q583jn3qhfpfk4frs05179wk
    FOREIGN KEY (credit_request_id)
    REFERENCES public.credit_requests(id);


-- Each credit request belongs to a credit facility.
ALTER TABLE ONLY public.credit_requests
    ADD CONSTRAINT fk5dw2jjua6398b1nkmvjptw0pc
    FOREIGN KEY (credit_limit_id)
    REFERENCES public.credit_limits(id);


-- Each user token belongs to a user.
ALTER TABLE ONLY public.user_tokens
    ADD CONSTRAINT fk61iiu6gfevpvo2v3yl76sar7r
    FOREIGN KEY (user_id)
    REFERENCES public.users(id);


-- Each group credit limit belongs to an institution.
ALTER TABLE ONLY public.group_credit_limits
    ADD CONSTRAINT fk6k35o89ep7814t2ay6ma1ubb
    FOREIGN KEY (financial_institution_id)
    REFERENCES public.financial_institutions(id);


-- Each group membership references a counterparty.
ALTER TABLE ONLY public.corporate_group_memberships
    ADD CONSTRAINT fk6t4brt1gv839hckgbr4f96ha2
    FOREIGN KEY (counterparty_id)
    REFERENCES public.counterparties(id);


-- Each user belongs to a financial institution.
ALTER TABLE ONLY public.users
    ADD CONSTRAINT fk78e95a4vh0d0b9fru9k8vrb8u
    FOREIGN KEY (financial_institution_id)
    REFERENCES public.financial_institutions(id);


-- Each group membership references a corporate group.
ALTER TABLE ONLY public.corporate_group_memberships
    ADD CONSTRAINT fk803g1sl1aqa8thtqoonk2xivq
    FOREIGN KEY (corporate_group_id)
    REFERENCES public.corporate_groups(id);


-- Each financial profile belongs to a counterparty.
ALTER TABLE ONLY public.counterparty_financial_profiles
    ADD CONSTRAINT fkcxqbucjrqmi3syy1et2aukcrq
    FOREIGN KEY (counterparty_id)
    REFERENCES public.counterparties(id);


-- Each approval decision references the deciding user.
ALTER TABLE ONLY public.approval_decisions
    ADD CONSTRAINT fkemds3a5ywqo8ufkc9abo8fm38
    FOREIGN KEY (decided_by_id)
    REFERENCES public.users(id);


-- An audit log may reference the user who performed the action.
ALTER TABLE ONLY public.audit_logs
    ADD CONSTRAINT fkf2uqqjmo7gvd8fq7ac81fgc0m
    FOREIGN KEY (actor_id)
    REFERENCES public.users(id);


-- Each group credit limit references a corporate group.
ALTER TABLE ONLY public.group_credit_limits
    ADD CONSTRAINT fkg95eavw937vuw7so4lapyl2t
    FOREIGN KEY (corporate_group_id)
    REFERENCES public.corporate_groups(id);


-- A password reset challenge may reference a user.
ALTER TABLE ONLY public.password_reset_codes
    ADD CONSTRAINT fkke97isexxbl8lf7yibo6q02ir
    FOREIGN KEY (user_id)
    REFERENCES public.users(id);


-- Each company credit limit belongs to an institution.
ALTER TABLE ONLY public.credit_limits
    ADD CONSTRAINT fkmhtxffdm01prtimogragrutkw
    FOREIGN KEY (financial_institution_id)
    REFERENCES public.financial_institutions(id);


-- Each email verification challenge belongs to a user.
ALTER TABLE ONLY public.email_verification_codes
    ADD CONSTRAINT fkpjww6kxejvkaaivcg6vv7r9w9
    FOREIGN KEY (user_id)
    REFERENCES public.users(id);


-- Each company credit limit references a counterparty.
ALTER TABLE ONLY public.credit_limits
    ADD CONSTRAINT fkq2n70wqbedqdhgh4uyomexk74
    FOREIGN KEY (counterparty_id)
    REFERENCES public.counterparties(id);


-- Each credit request references the user who submitted it.
