    REFERENCES public.users(id);


-- ============================================================
-- 6. INDEXES
-- ============================================================
--
-- An index helps PostgreSQL locate records efficiently.
--
-- Primary keys and UNIQUE constraints also create indexes
-- automatically in PostgreSQL.
--
-- This additional index supports queries that filter
-- exposure snapshots by reporting date.

CREATE INDEX credit_exposure_snapshots_reporting_date_idx
    ON public.credit_exposure_snapshots (reporting_date);


-- ============================================================
-- 7. COMPLETE DATABASE INITIALIZATION
-- ============================================================
--
-- COMMIT makes the transaction's changes permanent.
--
-- If initialization fails before COMMIT, the transaction
-- is not committed and the partial changes are rolled back.
--
-- After successful initialization:
--   1. The database structure exists.
--   2. Auth Service can validate its required tables.
--   3. Credit Service can validate its required tables.
--   4. Activity Service can use its email delivery queue.
--   5. Demo seeders can populate the database separately.
--
-- IMPORTANT:
-- This baseline is not designed to upgrade an existing
-- database. It must only be applied to an empty public schema.

COMMIT;


